def _install_bundled_modules():
    for _name, _payload in _BUNDLED_MODULES:
        _module = _types.ModuleType(_name)
        _module.__file__ = __file__ + ":" + _name
        _sys.modules[_name] = _module
        _source = _zlib.decompress(_b64.b85decode(_payload.encode("ascii"))).decode("utf-8")
