import argparse
import json
from pathlib import Path
import sys
from typing import Any, Iterable, Mapping


# 可直接在这里填写路径；命令行参数优先级更高。
# INPUT_PATH 可为 stringliteral.json，或包含它的目录。
DEFAULT_INPUT_PATH = r"D:\user\von\Workbench\data\projects\超级Z机器\game-name\bak\64\stringliteral.json"
DEFAULT_SCRIPT_JSON_PATH = r"D:\user\von\Workbench\data\projects\超级Z机器\game-name\bak\64\script.json"
DEFAULT_DUMP_CS_PATH = r"D:\user\von\Workbench\data\projects\超级Z机器\game-name\bak\64\dump.cs"
DEFAULT_LIBIL2CPP_PATH = r"D:\user\von\Workbench\data\projects\超级Z机器\game-name\game\lib\arm64-v8a\libil2cpp.so"
# 可选：原项目扫描生成的 records.json，用于确认同名静态显示文本。
DEFAULT_RECORDS_JSON_PATH = r""
# 留空时输出到 stringliteral.json 同目录的 output/Hook_Translate/ 下。
DEFAULT_OUTPUT_CPP_PATH = r""

from dynamic_translation_dictionary import (
    DYNAMIC_DICTIONARY_CPP_FILENAME,
    DYNAMIC_DICTIONARY_OUTPUT_SUBDIR,
    _ascii_case_key,
    _extract_stringliteral_candidate_roles,
    cpp_utf16_literal,
)
from il2cpp_display_usage import analyze_il2cpp_display_usage


def _existing_file(value: str | Path, label: str) -> Path:
    path = Path(value).expanduser().resolve()
    if not path.is_file():
        raise FileNotFoundError(f"未找到{label}: {path}")
    return path


def _resolve_stringliteral(value: str | Path) -> Path:
    path = Path(value).expanduser().resolve()
    if path.is_dir():
        path = path / "stringliteral.json"
    if path.name.lower() != "stringliteral.json":
        raise ValueError("输入必须是 stringliteral.json，或包含它的目录。")
    return _existing_file(path, "stringliteral.json")


def _addresses(rows: Any, label: str) -> list[int | str]:
    if not isinstance(rows, list):
        raise ValueError(f"显示分析缺少 {label} 数组。")
    result: list[int | str] = []
    for index, row in enumerate(rows):
        if not isinstance(row, Mapping) or not isinstance(row.get("address"), (int, str)):
            raise ValueError(f"显示分析 {label}[{index}] 缺少有效 address。")
        result.append(row["address"])
    return result


def _static_display_values(records_path: str | Path | None) -> set[str]:
    if not records_path:
        return set()
    path = _existing_file(records_path, "records.json")
    try:
        payload = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"records.json 读取失败: {path}: {exc}") from exc
    if not isinstance(payload, list):
        raise ValueError(f"records.json 顶层必须是数组: {path}")
    return {
        row["source_text"]
        for row in payload
        if isinstance(row, Mapping) and isinstance(row.get("source_text"), str)
    }


def _enum_sources(rows: Any) -> tuple[list[str], list[str]]:
    """仅保留分析器已经证明会进入显示入口的枚举成员。"""
    if not isinstance(rows, list):
        return [], []
    whole: list[str] = []
    substring: list[str] = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        members = row.get("members")
        roles = set(row.get("roles", [])) if isinstance(row.get("roles"), list) else set()
        if not isinstance(members, list):
            continue
        for member in members:
            if not isinstance(member, str) or not member:
                continue
            if "exact" in roles:
                whole.append(member)
            if "derived" in roles:
                substring.append(member)
    return whole, substring


def _unique_sources(sources: Iterable[str], *, longest_first: bool = False) -> list[str]:
    """与 Hook 的 ASCII 忽略大小写匹配规则一致，保留首个来源形式。"""
    result: list[str] = []
    seen: set[str] = set()
    for source in sources:
        if not isinstance(source, str) or not source or "\0" in source:
            continue
        key = _ascii_case_key(source)
        if key not in seen:
            seen.add(key)
            result.append(source)
    if longest_first:
        result.sort(key=lambda value: -len(value.encode("utf-16-le")))
    return result


def _render_array(name: str, sources: Iterable[str], *, longest_first: bool = False) -> list[str]:
    rows = [f"const NativeUnityTranslationEntry {name}[] = {{"]
    # 译文特意为 u\"\"：这是文本识别导出工具，不做翻译。
    rows.extend(f"    {{{cpp_utf16_literal(source)}, u\"\"}}," for source in _unique_sources(sources, longest_first=longest_first))
    rows.extend(["    {nullptr, nullptr},", "};"])
    return rows


def _render_dictionary(whole_sources: Iterable[str], substring_sources: Iterable[str]) -> str:
    rows = [
        "// Generated from stringliteral.json entries proven to reach a Unity display sink.",
        "// Translation slots are intentionally blank (u\"\") in this text-recognition-only export.",
        "// Exact literals use whole-text matching; derived literals use substring matching.",
    ]
    rows.extend(_render_array("kWholeTextDictionary", whole_sources))
    rows.append("")
    rows.extend(_render_array("kSubstringDictionary", substring_sources, longest_first=True))
    rows.append("")
    return "\n".join(rows)


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="识别 IL2CPP 动态显示文本并导出空译文 C++ 字典。")
    parser.add_argument("input_positional", nargs="?", help="stringliteral.json 或其所在目录")
    parser.add_argument("-i", "--input", help="输入路径；优先于代码顶部变量")
    parser.add_argument("--script-json", help="script.json；默认与 stringliteral.json 同目录")
    parser.add_argument("--dump-cs", help="dump.cs；默认与 stringliteral.json 同目录")
    parser.add_argument("--libil2cpp", help="ARM64 libil2cpp.so 路径")
    parser.add_argument("--records", help="可选的 records.json；优先于代码顶部变量")
    parser.add_argument("-o", "--output", help="最终 .cpp 文件路径；优先于代码顶部变量")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    input_value = args.input or args.input_positional or DEFAULT_INPUT_PATH
    if not input_value:
        raise ValueError("请设置 DEFAULT_INPUT_PATH，或通过 --input / 位置参数传入输入路径。")
    source_path = _resolve_stringliteral(input_value)
    script_path = _existing_file(args.script_json or DEFAULT_SCRIPT_JSON_PATH or source_path.with_name("script.json"), "script.json")
    dump_path = _existing_file(args.dump_cs or DEFAULT_DUMP_CS_PATH or source_path.with_name("dump.cs"), "dump.cs")
    so_value = args.libil2cpp or DEFAULT_LIBIL2CPP_PATH
    if not so_value:
        raise ValueError("请设置 DEFAULT_LIBIL2CPP_PATH，或通过 --libil2cpp 传入 libil2cpp.so。")
    so_path = _existing_file(so_value, "libil2cpp.so")
    static_display_values = _static_display_values(args.records or DEFAULT_RECORDS_JSON_PATH)
    output_value = args.output or DEFAULT_OUTPUT_CPP_PATH
    target_cpp = (
        Path(output_value).expanduser().resolve()
        if output_value
        else source_path.parent / "output" / DYNAMIC_DICTIONARY_OUTPUT_SUBDIR / DYNAMIC_DICTIONARY_CPP_FILENAME
    )
    if target_cpp.suffix.lower() != ".cpp":
        raise ValueError("输出路径必须是 .cpp 文件。")

    try:
        payload = json.loads(source_path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"stringliteral.json 读取失败: {source_path}: {exc}") from exc
    if not isinstance(payload, list):
        raise ValueError("stringliteral.json 顶层必须是数组。")

    print(f"[动态文本识别] 输入: {source_path}", flush=True)
    analysis = analyze_il2cpp_display_usage(
        libil2cpp_path=so_path,
        script_json_path=script_path,
        stringliteral_json_path=source_path,
        dump_cs_path=dump_path,
        use_cache=False,
        progress_callback=lambda message: print(f"[动态文本识别] {message}", flush=True),
    )
    candidates, whole_sources, substring_sources, _filtered, _reasons = _extract_stringliteral_candidate_roles(
        payload,
        exact_display_addresses=_addresses(analysis.get("exact_literals"), "exact_literals"),
        derived_display_addresses=_addresses(analysis.get("derived_influence"), "derived_influence"),
        static_display_values=static_display_values,
    )
    enum_whole, enum_substring = _enum_sources(analysis.get("display_enum_types", []))
    # candidates 是经过原项目同一套安全过滤后的文本；角色列表只会来自这些候选。
    allowed = set(candidates)
    whole_sources = [value for value in whole_sources if value in allowed] + enum_whole
    substring_sources = [value for value in substring_sources if value in allowed] + enum_substring
    whole_count = len(_unique_sources(whole_sources))
    substring_count = len(_unique_sources(substring_sources, longest_first=True))

    target_cpp.parent.mkdir(parents=True, exist_ok=True)
    target_cpp.write_text(_render_dictionary(whole_sources, substring_sources), encoding="utf-8")
    print(f"[动态文本识别] 已识别文本={len(candidates)}，整句={whole_count}，片段={substring_count}，静态交集={len(static_display_values)}", flush=True)
    print(f"[动态文本识别] C++ 空译文字典: {target_cpp}", flush=True)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (FileNotFoundError, ValueError, RuntimeError) as exc:
        print(f"[动态文本识别][失败] {exc}", file=sys.stderr, flush=True)
        raise SystemExit(1)
